<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$pdo=db();$uid=current_user()['id'];$s=$pdo->prepare("SELECT COUNT(*) FROM tb_transaksi WHERE status='masuk' AND id_user=?");$s->execute([$uid]);$active=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi WHERE DATE(waktu_masuk)=CURDATE() AND id_user=?');$s->execute([$uid]);$today=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COALESCE(SUM(biaya_total),0) FROM tb_transaksi WHERE status='keluar' AND DATE(waktu_keluar)=CURDATE() AND status_pembayaran='lunas' AND id_user_keluar=?");$s->execute([$uid]);$revenue=(float)$s->fetchColumn();$s=$pdo->prepare("SELECT COALESCE(SUM(biaya_total),0) FROM tb_transaksi WHERE status='keluar' AND DATE(waktu_keluar)=CURDATE() AND status_pembayaran='menunggu_verifikasi' AND id_user_keluar=?");$s->execute([$uid]);$pendingQris=(float)$s->fetchColumn();$areas=$pdo->query('SELECT * FROM tb_area_parkir ORDER BY nama_area')->fetchAll();$recentStmt=$pdo->prepare("SELECT t.id_parkir,t.waktu_masuk,t.status,k.plat_nomor,k.jenis_kendaraan,a.nama_area FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area WHERE t.id_user=? OR t.id_user_keluar=? ORDER BY t.id_parkir DESC LIMIT 6");$recentStmt->execute([$uid,$uid]);$recent=$recentStmt->fetchAll();render_header('Dashboard Petugas','dashboard');?>
<div class="page-intro"><div><h2>Operasional pribadi hari ini</h2><p>Rekap transaksi dan pendapatan hanya untuk transaksi yang Anda proses. Informasi kapasitas area tetap mencakup seluruh parkir.</p></div><a class="btn btn-primary" href="<?= h(url('petugas/transaksi-masuk.php')) ?>">＋ Kendaraan masuk</a></div><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">Sedang parkir</span><span class="stat-icon cyan">◷</span></div><div class="stat-value"><?= number_format($active) ?></div><div class="stat-foot">Transaksi masuk yang Anda proses</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Transaksi masuk hari ini</span><span class="stat-icon">↓</span></div><div class="stat-value"><?= number_format($today) ?></div><div class="stat-foot">Kendaraan masuk yang Anda proses hari ini</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Pendapatan hari ini</span><span class="stat-icon green">Rp</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($revenue)) ?></div><div class="stat-foot">Pembayaran berstatus lunas yang Anda proses</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">QRIS menunggu verifikasi</span><span class="stat-icon orange">◷</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($pendingQris)) ?></div><div class="stat-foot">Bukan pendapatan terverifikasi</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Area tersedia</span><span class="stat-icon orange">▦</span></div><div class="stat-value"><?= number_format(array_sum(array_map(fn($a)=>(int)$a['kapasitas']-(int)$a['terisi'],$areas))) ?></div><div class="stat-foot">Slot kosong dari semua area</div></article></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Status area parkir</h2><p>Jumlah terisi diperbarui oleh transaksi.</p></div></div><div class="panel-body"><?php foreach($areas as $a):$pct=(int)round((int)$a['terisi']/max(1,(int)$a['kapasitas'])*100);?><div style="margin-bottom:18px"><div class="area-top"><strong style="font-size:12px"><?= h($a['nama_area']) ?></strong><span style="font-size:11px;color:#77839a"><?= (int)$a['terisi'] ?>/<?= (int)$a['kapasitas'] ?></span></div><div class="progress"><span style="width:<?= min(100,$pct) ?>%;<?= $pct>=90?'background:#e65f71':'' ?>"></span></div><div class="area-foot"><span><?= $pct ?>% terisi</span><span><?= max(0,(int)$a['kapasitas']-(int)$a['terisi']) ?> slot tersedia</span></div></div><?php endforeach;if(!$areas): ?><div class="empty-state">Belum ada area parkir aktif.</div><?php endif; ?></div></section><section class="panel"><div class="panel-heading"><div><h2>Aksi cepat</h2><p>Pilih tugas operasional.</p></div></div><div class="panel-body" style="display:grid;gap:10px"><a class="btn btn-primary" href="<?= h(url('petugas/transaksi-masuk.php')) ?>">↓ Catat kendaraan masuk</a><a class="btn btn-secondary" href="<?= h(url('petugas/transaksi-keluar.php')) ?>">↑ Proses kendaraan keluar</a><a class="btn btn-secondary" href="<?= h(url('petugas/kendaraan-aktif.php')) ?>">◷ Lihat kendaraan aktif</a><a class="btn btn-secondary" href="<?= h(url('petugas/riwayat.php')) ?>">▤ Buka riwayat transaksi</a></div></section></div><section class="panel"><div class="panel-heading"><div><h2>Transaksi terbaru</h2><p>Transaksi yang melibatkan Anda sebagai petugas masuk atau keluar.</p></div><a class="btn btn-secondary btn-sm" href="<?= h(url('petugas/riwayat.php')) ?>">Riwayat →</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Plat Nomor</th><th>Jenis</th><th>Area</th><th>Waktu masuk</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td class="td-main"><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h($r['nama_area']) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= status_badge($r['status']) ?></td><td><?php if($r['status']==='keluar'): ?><a class="btn btn-secondary btn-sm" href="<?= h(url('petugas/struk.php?id='.(int)$r['id_parkir'])) ?>">Struk</a><?php else: ?><a class="btn btn-primary btn-sm" href="<?= h(url('petugas/transaksi-keluar.php?id='.(int)$r['id_parkir'])) ?>">Proses keluar</a><?php endif; ?></td></tr><?php endforeach;if(!$recent): ?><tr><td colspan="7"><div class="empty-state">Belum ada transaksi.</div></td></tr><?php endif; ?></tbody></table></div></section><?php render_footer(); ?>